                        best_global = (delta, i, pos, j, new_from, new_to)

        if best_global is None:
            return False

        delta, i, pos, j, new_from, new_to = best_global
        if delta >= 0:
            # allow slight non-worsening only if we clearly exceed the hint
            if hint is not None and hint > 0 and len(routes) > hint + 1:
                pass
            else:
                return False

        routes[i] = new_from
        routes[j] = new_to
        if not routes[i]:
            routes.pop(i)
        return True

    for _ in range(40):
        if len(routes) <= 1:
            break
        if not inter_relocate(routes):
            break

    # targeted edit: inter-route swap (deterministic best improving, limited to nearby candidates)
    def inter_swap(routes):
        n = len(routes)
        if n <= 1:
            return False
        loads = [route_load(r) for r in routes]
        costs = [route_cost(r) for r in routes]

        cust_list = list(instance["customer_ids"])
        topk = 6
        nearest = {}
        for v in cust_list:
            dv = []
            row_v = matrix[v]
            for u in cust_list:
                if u == v:
                    continue
                dv.append((row_v[u], u))
            dv.sort(key=lambda x: (x[0], x[1]))
            nearest[v] = [u for _, u in dv[:topk]]

        where = {}
        for i in range(n):
            for v in routes[i]:
                where[v] = i

        def route_cost_after_swap(ri, rp, rj, rq):
            # ri and rj are routes, rp/rq are positions
            a = ri[p]
            b = rj[q]
            new_ri = ri[:p] + [b] + ri[p + 1 :]
            new_rj = rj[:q] + [a] + rj[q + 1 :]
            return route_cost(new_ri), route_cost(new_rj), new_ri, new_rj

        best = None  # (delta, i, pi, j, pj, new_i, new_j)
        for i in range(n):
            ri = routes[i]
            if not ri:
                continue
            for pi in range(len(ri)):
                a = ri[pi]
                # candidate routes from nearest customers of a
                cand = set()
                for u in nearest.get(a, []):
                    if u in where:
                        jj = where[u]
                        if jj != i and routes[jj]:
                            cand.add(jj)
                cand = sorted(cand)
                if not cand:
                    continue
                for j in cand:
                    rj = routes[j]
                    for pj in range(len(rj)):
                        b = rj[pj]
                        # capacity feasibility
                        if loads[i] - demands[a] + demands[b] > capacity:
                            continue
                        if loads[j] - demands[b] + demands[a] > capacity:
                            continue
                        new_ci, new_cj, new_i, new_j = route_cost_after_swap(ri, pi, rj, pj)
                        delta = (new_ci + new_cj) - (costs[i] + costs[j])
                        if best is None or delta < best[0]:
                            best = (delta, i, pi, j, pj, new_i, new_j)

        if best is None:
            return False
        delta, i, pi, j, pj, new_i, new_j = best
        if delta >= 0:
            return False
        routes[i] = new_i
        routes[j] = new_j
        return True

    for _ in range(25):
        if len(routes) <= 1:
            break
        if not inter_swap(routes):
            break

    routes = [r for r in routes if r]
    return routes
